package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.databind.PropertyName;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

public class ObjectIdInfo_withAlwaysAsId_TriageGen0Test {

    /**
     * Helper to create an ObjectIdInfo instance using protected constructors via reflection 
     * or by assuming availability in the same package for testing purposes.
     * Since the prompt provides the constructor signatures, we use them.
     */
    private ObjectIdInfo createInstance(boolean alwaysAsId) {
        // Using the provided protected constructor signature:
        // protected ObjectIdInfo(PropertyName prop, Class<?> scope, Class<? extends ObjectIdGenerator<?>> gen, boolean alwaysAsId, Class<? extends ObjectIdResolver> resolver);
        return new ObjectIdInfo(
                null, 
                Object.class, 
                com.fasterxml.jackson.databind.ObjectIds.UUIDGenerator.class, 
                alwaysAsId, 
                com.fasterxml.jackson.databind.ObjectIds.PassThroughResolver.class
        );
    }

    @Test
    public void testWithAlwaysAsId_ReturnsSameInstance_WhenStateIsSame() {
        // Arrange
        ObjectIdInfo original = createInstance(true);

        // Act
        ObjectIdInfo result = original.withAlwaysAsId(true);

        // Assert
        assertSame("Should return the same instance if state is already true", original, result);
    }

    @Test
    public void testWithAlwaysAsId_ReturnsSameInstance_WhenStateIsSameFalse() {
        // Arrange
        ObjectIdInfo original = createInstance(false);

        // Act
        ObjectIdInfo result = original.withAlwaysAsId(false);

        // Assert
        assertSame("Should return the same instance if state is already false", original, result);
    }

    @Test
    public void testWithAlwaysAsId_ReturnsNewInstance_WhenStateChangesTrueToFalse() {
        // Arrange
        ObjectIdInfo original = createInstance(true);

        // Act
        ObjectIdInfo result = original.withAlwaysAsId(false);

        // Assert
        assertNotSame("Should return a new instance when state changes from true to false", original, result);
        assertEquals("New instance should have alwaysAsId as false", false, result.getAlwaysAsId());
    }

    @Test
    public void testWithAlwaysAsId_ReturnsNewInstance_WhenStateChangesFalseToTrue() {
        // Arrange
        ObjectIdInfo original = createInstance(false);

        // Act
        ObjectIdInfo result = original.withAlwaysAsId(true);

        // Assert
        assertNotSame("Should return a new instance when state changes from false to true", original, result);
        assertEquals("New instance should have alwaysAsId as true", true, result.getAlwaysAsId());
    }

    @Test
    public void testWithAlwaysAsId_MaintainsOtherProperties() {
        // Arrange
        // We need a real PropertyName to ensure properties are copied correctly
        // Since PropertyName is usually created via BeanProperty, we'll simulate with a minimal setup if possible
        // or rely on the fact that the constructor uses _propertyName, _scope, etc.

        // For the purpose of this test, we verify that the constructor call in the method 
        // uses the existing fields of the current object.

        // In a real scenario, we'd use a mock or a real PropertyName. 
        // Because we are testing the logic of the 'if' branch and the 'new' branch:
        ObjectIdInfo original = createInstance(false);

        // Act
        ObjectIdInfo result = original.withAlwaysAsId(true);

        // Assert
        assertNotSame(original, result);
        assertEquals(original.getGeneratorType(), result.getGeneratorType());
        assertEquals(original.getResolverType(), result.getResolverType());
        assertEquals(original.getScope(), result.getScope());
        assertEquals(true, result.getAlwaysAsId());
    }
}
